function restore():Draft {try {const value=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(value&&(value.stage==='library'||STEPS.some(s=>s.key===value.stage))&&Array.isArray(value.placements)&&Array.isArray(value.sections))return {...initialDraft(),...value,formSet:value.formSet||(value.formConfigured?'自定义':'Agent 推荐'),placements:value.placements.map((item:Placement)=>({...initialDraft().placements.find(p=>p.name===item.name),...item})),stage:value.stage==='plan'||value.stage==='preview'?'edit':value.stage==='brief'?'templates':value.stage}}catch{}return initialDraft()}

