 const [leadIndex,setLeadIndex]=useState(0)
 const [simulateMatch,setSimulateMatch]=useState('符合条件')
 const [linkError,setLinkError]=useState('')
 const timer=useRef<ReturnType<typeof setTimeout>|null>(null)
 const toastTimer=useRef<ReturnType<typeof setTimeout>|null>(null)
 const localPreview=new URLSearchParams(location.search).has('studio-preview')
 const template=draft.templateId==='custom'?{...mockTemplatesData.find(t=>t.type===(draft.optionalFields['_pageType']||'产品营销'))!,id:'custom',name:'自定义组件'}:mockTemplatesData.find(t=>t.id===draft.templateId)||mockTemplatesData[0]
 const selectedPlacement=draft.placements.find(p=>p.name===activePosition)!
 const update=(patch:Partial<Draft>)=>setDraft(d=>{const next={...d,...patch};const changed=brandSnapshotKey(next)!==brandSnapshotKey(d);return {...next,revision:changed?Math.max(d.revision+1,patch.revision||0):d.revision,updatedAt:new Date().toISOString()}})
 const configure=(patch:Partial<Draft>)=>update(applyConfiguration(draft,patch))
 const notify=(message:string)=>{setToast(message);if(toastTimer.current)clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),3500)}
 const run=(label:string,done:()=>void)=>{setBusy(label);timer.current=setTimeout(()=>{setBusy('');done()},950)}
 const dirty=(patch:Partial<Draft>)=>configure({...patch,linkReady:false})
 useEffect(()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(draft))}catch{setToast('本地存储空间不足，当前修改仅保留在会话中。')}},[draft])
 useEffect(()=>()=>{if(timer.current)clearTimeout(timer.current);if(auditTimer.current)clearTimeout(auditTimer.current);if(toastTimer.current)clearTimeout(toastTimer.current)},[])
 useEffect(()=>{if(!draft.templateId)return;setPages(rows=>{const previous=rows.find(r=>r.id===draft.id);return [{...previous,id:draft.id,draft},...rows.filter(r=>r.id!==draft.id)]})},[draft])
 useEffect(()=>{try{localStorage.setItem(PAGES_KEY,JSON.stringify(pages))}catch{setToast('历史页面保存失败，本地空间不足。')}},[pages])
 const auditReport=draft.websiteAudit?.capability==='brand_consistency'?draft.websiteAudit:undefined
