 const runBrandAudit=()=>{if(auditPhase)return;const snapshot=structuredClone(draft);setAuditPhase('品牌一致性检测中');auditTimer.current=setTimeout(()=>{const report=inspectBrandConsistency(snapshot);setDraft(current=>current.id===snapshot.id?{...current,websiteAudit:report}:current);setAuditPhase('')},700)}
 const autoOptimizeBrand=(findingId:string)=>{if(auditPhase||!optimizeBrandFinding(draft,auditReport,findingId))return;setAuditPhase('品牌一致性优化中');setOptimizingFindingId(findingId);auditTimer.current=setTimeout(()=>{setDraft(current=>{const next=optimizeBrandFinding(current,auditReport,findingId);return next?{...next,messages:[...current.messages,{role:'生成助手',text:'已按确认的品牌方案自动优化对应位置，修改已保存到当前草稿。'}]}:current});setAuditPhase('');setOptimizingFindingId('')},800)}
 const composeBrandSolution=(text:string)=>{setSelectedElement('');setActiveGap('');setEditorTab('对话');setEditText(text);setModal('');notify('方案已填入生成助手，发送后执行。')}
 const filteredPages=pages.filter(p=>(p.draft.title+p.draft.company).includes(pageQuery)&&(pageStatus==='全部状态'||pageStatus===(p.draft.published?(p.draft.paused?'已暂停':'已发布'):'草稿')))
 const openPage=(page:SavedPage,stage?:Stage)=>{setAiGap(null);setAiBatch([]);setSelectedElement('');setDraft({...initialDraft(),...page.draft,formSet:page.draft.formSet||(page.draft.formConfigured?'自定义':'Agent 推荐'),placements:page.draft.placements.map(item=>({...initialDraft().placements.find(p=>p.name===item.name)!,...item})),stage:stage||(page.draft.confirmed?'edit':'templates')});setSnapshot(null);setEditText('');setAppliedEdit('');setPreviewMode(false);setActiveGap('');setPendingImage('');setPendingKnowledge('')}
 const beginNew=()=>{setAiGap(null);setAiBatch([]);setSelectedElement('');setDraft({...initialDraft(),stage:'templates'});setSnapshot(null);setModal('');setFilter('全部模板');setAppliedEdit('');setPendingImage('');setPendingKnowledge('');setMockMissing(false);setActiveGap('');setEditText('');setEditorTab('对话');setMobile(false);setTablet(false)}
 const runIntentTask=(task:IntentTask)=>{const old=pages.find(p=>p.draft.agentTask?.request.requestId===task.requestId&&p.draft.agentTask.request.siteId===task.siteId);if(old){if(intentTaskKey(old.draft.agentTask?.request)!==intentTaskKey(task)){notify('同一请求标识的参数已变化，请使用新的 requestId。');return}openPage(old,'edit');setModal('');notify('已打开该请求的已有页面。');return}const t=mockTemplatesData.find(t=>t.id===task.generation.templateId)!;const next=draftFromIntentTask({...initialDraft(),company:draft.company,website:draft.website,industry:draft.industry,business:draft.business,logo:draft.logo},task,t);setSelectedElement('');setPreviewMode(false);setEditorTab('对话');setModal('');handleGenerate(next.generationRequest!);run('生成助手 · 根据导入意图生成页面',()=>setDraft(next))}
