 const preparePlan=()=>run('生成助手 · 拟定方案并检查资料',()=>{const sections=draft.visitorIntent?.sections||template.sections;update({stage:'plan',sections:sections.map((title,i)=>({id:`s${i}`,title,body:CONTENT[i]})),imageReady:!mockMissing,knowledgeReady:!mockMissing,validated:!mockMissing,seoTitle:`${draft.title} | ${draft.company}`,seoDescription:draft.need});notify(mockMissing?'营销页检测助手：示例资料存在缺口，请补充后重新校验。':'营销页检测助手：已匹配企业示例资料，校验通过。')})
 const preparePublish=()=>{if(publishReasons.length){setModal('supplement');notify(publishReasons[0]);return}if(draft.promote&&draft.placements.some(p=>p.enabled&&(p.startTime||'00:00')>(p.endTime||'23:59'))){notify('展示开始时间不能晚于结束时间。');return}if(draft.promote&&draft.placements.some(p=>p.enabled&&p.name!=='首屏 Banner'&&p.name!=='智能客服推送'&&p.scopes?.length===0)){notify('请为已启用的推广位置选择展示范围。');return}if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(draft.slug)){setLinkError('请输入有效的页面路径。');notify('页面路径无效，请展开页面链接设置修改。');return}setReleaseBump(currentVersion(pages.find(p=>p.id===draft.id))?'patch':'major');setReleaseSummary('');setModal('confirmPublish')}
