 const checkSupplement=()=>{if(!draft.pendingSupplement){notify('请先补充实际资料，再验证。');return}setModal('');const base=draft;const baseKey=brandSnapshotKey(base);const targets=base.supplementTargets?.length?base.supplementTargets:inspectMarketingPage(base).flatMap(g=>g.targetComponentIds);const next=applySupplementContent(base,base.pendingSupplement!,targets);const remaining=inspectMarketingPage(next);const resolved=inspectMarketingPage(base).filter(g=>!remaining.some(item=>item.id===g.id));const changedBlocks=Object.keys(base.pendingSupplement!).map(key=>({productIds:'PRODUCTS_JSON',formFields:'FORM_JSON',image:'IMAGE_ASSETS',elementImages:'IMAGE_ASSETS',assets:'UPLOADED_MATERIALS',supplementText:'UPLOADED_MATERIALS',componentInputs:'UPLOADED_MATERIALS',knowledgeDirs:'KNOWLEDGE_SCOPE_JSON'}[key]||'PAGE_INPUT'));const request=buildContinuationRequest(base,template,{operation:'resume',targetComponentIds:targets,changedBlocks:[...new Set(changedBlocks)],resolvedGapIds:resolved.map(g=>g.id)},next);handleGenerate(request);run('正在验证补充内容并继续生成',()=>{setDraft(current=>{if(current.id!==base.id||current.revision!==base.revision||brandSnapshotKey(current)!==baseKey||current.need!==base.need||current.intentText!==base.intentText||current.pendingSupplement!==base.pendingSupplement){notify('页面已修改，补充资料已保留，请重新验证。');return current}return {...next,lastOperationRequest:request,revision:current.revision+1,updatedAt:new Date().toISOString(),validated:remaining.length===0,messages:[...current.messages,{role:'生成助手',text:resolved.length?`已补齐${resolved.map(g=>g.label).join('、')}，对应区域已更新。${remaining.length?`仍有 ${remaining.length} 项待补充，已保留占位。`:'可以继续编辑与预览。'}`:'已应用补充内容，其他区域可继续编辑或交给 AI 完善。'}]}});setActiveGap('')})}


