 const addBlock=(kind:BlockKind,before?:string)=>{setSelectedElement('');const block=BLOCKS.find(b=>b.kind===kind)!;const section=createComponent(kind,generateId(),block.label);const rows=[...draft.sections];const index=rows.findIndex(s=>s.id===before);rows.splice(index<0?rows.length:index,0,section);update({sections:rows,revision:draft.revision+1});setSelectedSection(section.id)}
